# ────────────────────────────────────────────
# AUTENTICAÇÃO & DADOS
# ────────────────────────────────────────────
_SALT = "PTMadvocacia2024"
# Usa Railway Volume (/data) se disponível, senão /tmp (efêmero)
_DADOS_PATH = "/data/ptm_dados.json" if os.path.isdir("/data") else "/tmp/ptm_dados.json"

def _hash(senha: str) -> str:
    return hashlib.sha256((_SALT + senha).encode()).hexdigest()

def _ok(senha: str, h: str) -> bool:
    return hmac.compare_digest(_hash(senha), h)

def _dados_padrao() -> dict:
    return {
        "usuarios": {
            "admin": {"nome": "Administrador", "hash": _hash("ptm2024"), "admin": True}
        },
        "advogados": [
            {"nome": "JULIO FRANCO POLI", "oab": "OAB/TO 4.589B",
             "endereco": "Qd. 106 Norte, Al. 02, Conj. L, Lote 04/05, Ed. Palmas Business Center, Sala 905, Palmas – TO"}
        ],
        "clientes": []
    }

def carregar_dados() -> dict:
    # Carrega base: arquivo salvo ou padrão
    dados = None
    if os.path.exists(_DADOS_PATH):
        try:
            with open(_DADOS_PATH, "r", encoding="utf-8") as f:
                dados = json.load(f)
        except Exception:
            pass
    if dados is None:
        dados = _dados_padrao()
        # Tenta carregar dos secrets do Streamlit
        try:
            for uname, info in st.secrets.get("usuarios", {}).items():
                dados["usuarios"][uname] = {
                    "nome": info.get("nome", uname),
                    "hash": _hash(info.get("senha", "")),
                    "admin": bool(info.get("admin", False))
                }
        except Exception:
            pass
        try:
            raw = st.secrets.get("dados", {}).get("advogados_json", None)
            if raw:
                dados["advogados"] = json.loads(raw)
        except Exception:
            pass
    # Sempre re-aplica variáveis de ambiente (garante usuários do env mesmo após restart)
    # Suporte a JSON (legado)
    try:
        env_usuarios = os.environ.get("USUARIOS_JSON", "")
        if env_usuarios:
            for uname, info in json.loads(env_usuarios).items():
                dados["usuarios"][uname] = {
                    "nome": info.get("nome", uname),
                    "hash": _hash(info.get("senha", "")),
                    "admin": bool(info.get("admin", False))
                }
    except Exception:
        pass
    # Suporte a variáveis simples: PTM_USER_<LOGIN>_SENHA e PTM_USER_<LOGIN>_NOME
    # Só cria usuário do env se ainda NÃO existe no JSON salvo e NÃO foi excluído pelo admin
    _env_deleted = set(dados.get("_env_users_deleted", []))
    for key, val in os.environ.items():
        if key.startswith("PTM_USER_") and key.endswith("_SENHA") and val:
            login = key[len("PTM_USER_"):-len("_SENHA")].lower()
            if login in _env_deleted or login in dados["usuarios"]:
                continue  # respeita edições/exclusões feitas pelo admin
            nome = os.environ.get(f"PTM_USER_{login.upper()}_NOME", login)
            admin = os.environ.get(f"PTM_USER_{login.upper()}_ADMIN", "false").lower() == "true"
            dados["usuarios"][login] = {
                "nome": nome,
                "hash": _hash(val),
                "admin": admin
            }
    try:
        env_adv = os.environ.get("ADVOGADOS_JSON", "")
        if env_adv:
            dados["advogados"] = json.loads(env_adv)
    except Exception:
        pass
    # Garante que a chave "clientes" existe
    dados.setdefault("clientes", [])
    return dados

def salvar_dados(dados: dict):
    try:
        # Escreve primeiro em arquivo temporário para evitar corrupção
        tmp = _DADOS_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(dados, f, ensure_ascii=False, indent=2)
        os.replace(tmp, _DADOS_PATH)
    except Exception as e:
        st.error(f"⚠️ Erro ao salvar dados: {e}\nCaminho: {_DADOS_PATH}")
        raise


