def login_page():
    _css()
    _, c, _ = st.columns([1,2,1])
    with c:
        st.markdown('<div class="ptm-login-wrap">', unsafe_allow_html=True)
        st.image(_logo(), use_container_width=True)
        st.markdown('<p class="ptm-login-title">Poli, Tertuliano & Mantovani</p>', unsafe_allow_html=True)
        st.markdown('<p class="ptm-login-sub">Gerador de Documentos</p>', unsafe_allow_html=True)
        st.markdown('<hr class="ptm-sep">', unsafe_allow_html=True)
        usuario = st.text_input("Usuário", key="login_user")
        senha   = st.text_input("Senha", type="password", key="login_pass")
        if st.button("Entrar", use_container_width=True):
            dados = carregar_dados()
            users = dados.get("usuarios", {})
            if usuario in users and _ok(senha, users[usuario]["hash"]):
                st.session_state.autenticado = True
                st.session_state.usuario = usuario
                st.session_state.nome_usuario = users[usuario]["nome"]
                st.session_state.is_admin = users[usuario].get("admin", False)
                st.rerun()
            else:
                st.error("Usuário ou senha incorretos.")
        st.markdown('</div>', unsafe_allow_html=True)

