# HELPERS DE FORMULÁRIO
# ────────────────────────────────────────────
def formatar_real(valor_str: str) -> str:
    raw = re.sub(r"[^\d]", "", valor_str.split(",")[0])
    if not raw:
        return valor_str
    n = int(raw)
    return "R$ {:,.2f}".format(n).replace(",", "X").replace(".", ",").replace("X", ".")

def numero_por_extenso(valor_str: str) -> str:
    raw = re.sub(r"[^\d]", "", valor_str.split(",")[0])
    if not raw:
        return ""
    n = int(raw)
    if n == 0:
        return "zero reais"
    U = ["","um","dois","três","quatro","cinco","seis","sete","oito","nove",
         "dez","onze","doze","treze","quatorze","quinze","dezesseis","dezessete",
         "dezoito","dezenove"]
    D = ["","","vinte","trinta","quarenta","cinquenta","sessenta","setenta","oitenta","noventa"]
    C = ["","cem","duzentos","trezentos","quatrocentos","quinhentos","seiscentos",
         "setecentos","oitocentos","novecentos"]
    def ate999(x):
        if x == 100: return "cem"
        c,r = divmod(x,100)
        partes = []
        if c: partes.append(C[c])
        if r < 20:
            if r: partes.append(U[r])
        else:
            d,u = divmod(r,10)
            partes.append(D[d])
            if u: partes.append(U[u])
        return " e ".join(partes)
    partes = []
    mi, resto = divmod(n, 1_000_000)
    if mi:
        label = "um milhão" if mi==1 else ate999(mi)+" milhões"
        partes.append(label)
    mil, resto = divmod(resto, 1000)
    if mil:
        label = "mil" if mil==1 else ate999(mil)+" mil"
        partes.append(label)
    if resto:
        partes.append(ate999(resto))
    texto = " e ".join(partes)
    return texto + " reais"

def _fmt_honorario_fixo(key: str):
    raw = re.sub(r"[^\d]", "", st.session_state.get(key, "").split(",")[0])
    if raw:
        n = int(raw)
        fmt = "R$ {:,.2f}".format(n).replace(",","X").replace(".",",").replace("X",".")
        st.session_state[key] = fmt

def _fmt_cpf():
    raw = re.sub(r"\D","",st.session_state.get("cpf_input",""))[:11]
    if len(raw)<=3: fmt=raw
    elif len(raw)<=6: fmt=f"{raw[:3]}.{raw[3:]}"
    elif len(raw)<=9: fmt=f"{raw[:3]}.{raw[3:6]}.{raw[6:]}"
    else: fmt=f"{raw[:3]}.{raw[3:6]}.{raw[6:9]}-{raw[9:]}"
    st.session_state["cpf_input"]=fmt

def _fmt_cnpj():
    raw = re.sub(r"\D","",st.session_state.get("cnpj_input",""))[:14]
    if len(raw)<=2: fmt=raw
    elif len(raw)<=5: fmt=f"{raw[:2]}.{raw[2:]}"
    elif len(raw)<=8: fmt=f"{raw[:2]}.{raw[2:5]}.{raw[5:]}"
    elif len(raw)<=12: fmt=f"{raw[:2]}.{raw[2:5]}.{raw[5:8]}/{raw[8:]}"
    else: fmt=f"{raw[:2]}.{raw[2:5]}.{raw[5:8]}/{raw[8:12]}-{raw[12:]}"
    st.session_state["cnpj_input"]=fmt

