def data_extenso() -> str:
    hoje = date.today()
    return f"Palmas-TO, {hoje.day} de {MESES[hoje.month]} de {hoje.year}."

def add_run(para, text, bold=False, italic=False, size_pt=12):
    r = para.add_run(text)
    r.bold = bold
    r.italic = italic
    r.font.size = Pt(size_pt)
    r.font.name = "Times New Roman"

def add_img(para, b64_str, width_inches=6.3):
    buf = io.BytesIO(base64.b64decode(b64_str))
    para.add_run().add_picture(buf, width=Inches(width_inches))

def spacer(doc, n=1):
    for _ in range(n):
        p = doc.add_paragraph()
        p.paragraph_format.space_before = Pt(0)
        p.paragraph_format.space_after  = Pt(0)

def setup_doc():
    doc = Document()
    sec = doc.sections[0]
    sec.page_width    = Emu(7773670)
    sec.page_height   = Emu(12803505)
    sec.top_margin    = Emu(1108710)
    sec.bottom_margin = Emu(1080135)
    sec.left_margin   = Emu(1080135)
    sec.right_margin  = Emu(1080135)
    hdr = sec.header.paragraphs[0]
    hdr.alignment = WD_ALIGN_PARAGRAPH.CENTER
    add_img(hdr, HEADER_B64)
    ftr = sec.footer.paragraphs[0]
    ftr.alignment = WD_ALIGN_PARAGRAPH.CENTER
    add_img(ftr, FOOTER_B64)
    return doc

def doc_to_bytes(doc):
    buf = io.BytesIO()
    doc.save(buf)
    buf.seek(0)
    return buf.getvalue()

ENDERECO_ESCRITORIO = ("Qd. 106 Norte, Al. 02, Conj. L, Lote 04/05, "
                       "Ed. Palmas Business Center, Sala 905, Palmas – TO")

def _texto_outorgados(advogados: list) -> list:
    """Retorna lista de strings descrevendo cada outorgado."""
    linhas = []
    for adv in advogados:
        txt = (adv["nome"] + ", advogado, inscrito na " + adv["oab"] +
               ", domiciliado profissionalmente na " + ENDERECO_ESCRITORIO + ".")
        linhas.append(txt)
    return linhas

