# 1. PROCURAÇÃO
# ─────────────────────────────────────────────
def gerar_procuracao(nome, cpf_cnpj, endereco, tipo, rg, nacionalidade,
                     estado_civil, objeto_acao="", advogados=None):
    if not advogados:
        advogados = []
    doc = setup_doc()
    spacer(doc, 3)

    titulo = doc.add_paragraph()
    titulo.alignment = WD_ALIGN_PARAGRAPH.CENTER
    titulo.paragraph_format.space_before = Pt(0)
    titulo.paragraph_format.space_after  = Pt(0)
    add_run(titulo, "PROCURAÇÃO", bold=True, size_pt=16)
    spacer(doc, 2)

    p = doc.add_paragraph()
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after  = Pt(0)
    add_run(p, "OUTORGANTE: ", bold=True)
    spacer(doc)

    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after  = Pt(0)
    add_run(p, nome.upper(), bold=True)
    if tipo == "pj":
        add_run(p, ", pessoa jurídica de direito privado, inscrita no CNPJ n. "
                   + cpf_cnpj + ", com sede a " + endereco + ".")
    else:
        trecho = ", " + nacionalidade
        if estado_civil:
            trecho += ", " + estado_civil
        if rg:
            trecho += ", portador(a) do RG n. " + rg + " e CPF n. " + cpf_cnpj
        else:
            trecho += ", inscrito(a) no CPF n. " + cpf_cnpj
        trecho += ", residente e domiciliado(a) em " + endereco + "."
        add_run(p, trecho)

    spacer(doc)
    p = doc.add_paragraph()
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after  = Pt(0)
    label_out = "OUTORGADOS: " if len(advogados) > 1 else "OUTORGADO: "
    add_run(p, label_out, bold=True)
    spacer(doc)

    linhas_adv = _texto_outorgados(advogados)
    for i, linha in enumerate(linhas_adv):
        p2 = doc.add_paragraph()
        p2.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        p2.paragraph_format.space_before = Pt(0)
        p2.paragraph_format.space_after  = Pt(0)
        # Nome em negrito, qualificação normal
        partes = linha.split(",", 1)
        add_run(p2, partes[0], bold=True)
        if len(partes) > 1:
            add_run(p2, "," + partes[1])
        if i < len(linhas_adv) - 1:
            spacer(doc)

    spacer(doc)
    p = doc.add_paragraph()
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after  = Pt(0)
    add_run(p, "PODERES: ", bold=True)
    spacer(doc)

    p3 = doc.add_paragraph()
    p3.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p3.paragraph_format.space_before = Pt(0)
    p3.paragraph_format.space_after  = Pt(0)
    poderes = ("Pelo presente instrumento particular de mandato, o outorgante "
               "nomeia e constitui seu bastante procurador o outorgado acima "
               "qualificado, a quem confere poderes para representá-lo(a) "
               "perante quaisquer Juízos, Tribunais e Instâncias, bem como "
               "perante repartições públicas federais, estaduais e municipais, "
               "autarquias e entidades paraestatais, podendo praticar todos os "
               "atos necessários ao fiel cumprimento deste mandato, inclusive "
               "os da cláusula ad judicia, com poderes para: propor ações e "
               "acompanhá-las em todos os seus termos; contestar, impugnar, "
               "recorrer; receber citação inicial; firmar compromisso; "
               "substabelecer com ou sem reservas; receber e dar quitação; "
               "confessar; desistir; transigir; acordar; pactuar; requerer "
               "medidas urgentes; fazer sustentação oral; representar junto à "
               "Receita Federal, Justiça do Trabalho, Justiça Estadual e "
               "Federal, e praticar todos os demais atos que se fizerem "
               "necessários")
    if objeto_acao.strip():
        poderes += (", especialmente para defender os interesses do outorgante "
                    "em " + objeto_acao.strip() + ".")
    else:
        poderes += "."
    add_run(p3, poderes)

    spacer(doc, 3)
    p_data = doc.add_paragraph()
    p_data.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p_data.paragraph_format.space_before = Pt(0)
    p_data.paragraph_format.space_after  = Pt(0)
    add_run(p_data, data_extenso())
    spacer(doc, 3)
    p_ass = doc.add_paragraph()
    p_ass.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p_ass.paragraph_format.space_before = Pt(0)
    p_ass.paragraph_format.space_after  = Pt(0)
    add_run(p_ass, "_" * 50)
    p_nome = doc.add_paragraph()
    p_nome.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p_nome.paragraph_format.space_before = Pt(0)
    p_nome.paragraph_format.space_after  = Pt(0)
    add_run(p_nome, nome.upper(), bold=True)
    return doc_to_bytes(doc)

