# PAINEL ADMIN
# ────────────────────────────────────────────
def painel_admin(dados):
    st.subheader("⚙️ Painel do Administrador")

    tab_u, tab_a, tab_diag = st.tabs(["👥 Usuários", "⚖️ Advogados", "🔧 Diagnóstico"])

    # ── Tab usuários ──
    with tab_u:
        st.markdown("### Usuários cadastrados")
        users = dados.get("usuarios", {})
        for uname, info in list(users.items()):
            with st.expander(f"{'🔑 ' if info.get('admin') else '👤 '}{info['nome']} ({uname})"):
                novo_nome = st.text_input("Nome de exibição", value=info["nome"], key="nome_"+uname)
                nova_senha = st.text_input("Nova senha (deixe em branco para não alterar)",
                                           type="password", key="pw_"+uname)
                admin_check = st.checkbox("Administrador", value=info.get("admin", False),
                                          key="adm_"+uname)
                col1, col2 = st.columns(2)
                with col1:
                    if st.button("💾 Salvar", key="save_"+uname):
                        dados["usuarios"][uname]["nome"] = novo_nome
                        dados["usuarios"][uname]["admin"] = admin_check
                        if nova_senha.strip():
                            dados["usuarios"][uname]["hash"] = _hash(nova_senha.strip())
                        salvar_dados(dados)
                        st.success("Salvo!")
                        st.rerun()
                with col2:
                    if uname != st.session_state.usuario:
                        if st.button("🗑️ Excluir", key="del_"+uname):
                            del dados["usuarios"][uname]
                            # Se o usuário veio de env var, marca para não ser recriado
                            if os.environ.get(f"PTM_USER_{uname.upper()}_SENHA"):
                                _del_list = dados.get("_env_users_deleted", [])
                                if uname not in _del_list:
                                    _del_list.append(uname)
                                dados["_env_users_deleted"] = _del_list
                            salvar_dados(dados)
                            st.success("Excluído.")
                            st.rerun()

        st.markdown("---")
        st.markdown("### Adicionar usuário")
        c1, c2 = st.columns(2)
        with c1:
            novo_login = st.text_input("Login (sem espaços)", key="new_login")
            novo_displayname = st.text_input("Nome de exibição", key="new_nome")
        with c2:
            nova_senha_new = st.text_input("Senha", type="password", key="new_pw")
            novo_admin = st.checkbox("Administrador", key="new_adm")
        if st.button("➕ Adicionar usuário"):
            if novo_login.strip() and nova_senha_new.strip() and novo_displayname.strip():
                login_key = novo_login.strip().lower().replace(" ", "_")
                dados["usuarios"][login_key] = {
                    "nome": novo_displayname.strip(),
                    "hash": _hash(nova_senha_new.strip()),
                    "admin": novo_admin
                }
                salvar_dados(dados)
                st.success(f"Usuário '{login_key}' adicionado!")
                st.rerun()
            else:
                st.error("Preencha login, nome e senha.")

    # ── Tab advogados ──
    with tab_a:
        st.markdown("### Advogados cadastrados")
        advs = dados.get("advogados", [])
        for i, adv in enumerate(advs):
            with st.expander(f"⚖️ {adv['nome']} – {adv['oab']}"):
                n_nome = st.text_input("Nome completo", value=adv["nome"], key=f"adv_nome_{i}")
                n_oab  = st.text_input("OAB", value=adv["oab"], key=f"adv_oab_{i}")
                st.caption(f"Endereço: {ENDERECO_ESCRITORIO}")
                c1, c2 = st.columns(2)
                with c1:
                    if st.button("💾 Salvar", key=f"adv_save_{i}"):
                        dados["advogados"][i] = {"nome": n_nome, "oab": n_oab}
                        salvar_dados(dados)
                        st.success("Salvo!")
                        st.rerun()
                with c2:
                    if st.button("🗑️ Excluir", key=f"adv_del_{i}"):
                        dados["advogados"].pop(i)
                        salvar_dados(dados)
                        st.success("Excluído.")
                        st.rerun()

        st.markdown("---")
        st.markdown("### Adicionar advogado")
        a1, a2 = st.columns(2)
        with a1:
            new_adv_nome = st.text_input("Nome completo (maiúsculas)", key="new_adv_nome")
        with a2:
            new_adv_oab  = st.text_input("OAB (ex: OAB/TO 4.589B)", key="new_adv_oab")
        st.caption(f"Endereço profissional (fixo): {ENDERECO_ESCRITORIO}")
        if st.button("➕ Adicionar advogado"):
            if new_adv_nome.strip() and new_adv_oab.strip():
                dados["advogados"].append({
                    "nome": new_adv_nome.strip().upper(),
                    "oab": new_adv_oab.strip(),
                })
                salvar_dados(dados)
                st.success("Advogado adicionado!")
                st.rerun()
            else:
                st.error("Preencha nome e OAB.")

    # ── Tab diagnóstico ──
    with tab_diag:
        st.markdown("### 🔧 Diagnóstico de Armazenamento")
        import datetime as _dt

        # Caminho ativo
        st.markdown(f"**Caminho do arquivo:** `{_DADOS_PATH}`")

        # Checa /data
        data_dir_existe = os.path.isdir("/data")
        st.markdown(f"**Diretório /data existe:** {'✅ Sim' if data_dir_existe else '❌ Não (usando /tmp)'}")

        # Checa se o arquivo existe
        arquivo_existe = os.path.exists(_DADOS_PATH)
        st.markdown(f"**Arquivo de dados existe:** {'✅ Sim' if arquivo_existe else '❌ Não (será criado no próximo save)'}")

        if arquivo_existe:
            stat = os.stat(_DADOS_PATH)
            st.markdown(f"**Tamanho do arquivo:** {stat.st_size} bytes")
            modificado = _dt.datetime.fromtimestamp(stat.st_mtime).strftime("%d/%m/%Y %H:%M:%S")
            st.markdown(f"**Última modificação:** {modificado}")

        # Teste de escrita
        st.markdown("---")
        if st.button("🔬 Testar escrita agora"):
            teste_path = ("/data/_teste_escrita.txt" if data_dir_existe else "/tmp/_teste_escrita.txt")
            try:
                with open(teste_path, "w") as f:
                    f.write("ok")
                os.remove(teste_path)
                st.success(f"✅ Escrita em `{teste_path}` funcionou!")
            except Exception as ex:
                st.error(f"❌ Falha ao escrever em `{teste_path}`: {ex}")

        # Forçar re-save dos dados atuais
        st.markdown("---")
        if st.button("💾 Forçar gravação dos dados agora"):
            try:
                salvar_dados(dados)
                st.success(f"✅ Dados gravados em `{_DADOS_PATH}`  ({len(dados.get('clientes',[]))} clientes, {len(dados.get('usuarios',{}))} usuários, {len(dados.get('advogados',[]))} advogados)")
            except Exception as ex:
                st.error(f"❌ Erro ao salvar: {ex}")

