# BANCO DE CLIENTES – CRUD
# ────────────────────────────────────────────
def _novo_cliente_vazio(tipo="PF"):
    return {
        "id": str(uuid.uuid4())[:8],
        "tipo": tipo,
        # PF
        "nome": "", "cpf": "", "rg": "", "orgao_rg": "",
        "estado_civil": "", "profissao": "", "nacionalidade": "brasileiro(a)", "naturalidade": "",
        # PJ
        "razao_social": "", "cnpj": "", "nome_fantasia": "",
        "socio_nome": "", "socio_cpf": "", "socio_rg": "", "socio_cargo": "",
        # Comuns
        "telefone": "", "email": "",
        "endereco": "", "numero": "", "complemento": "", "bairro": "",
        "cidade": "", "estado": "TO", "cep": "",
    }

def salvar_cliente(dados, cliente):
    clientes = dados.setdefault("clientes", [])
    for i, c in enumerate(clientes):
        if c.get("id") == cliente.get("id"):
            clientes[i] = cliente
            salvar_dados(dados)
            return
    clientes.append(cliente)
    salvar_dados(dados)

def excluir_cliente(dados, cliente_id):
    dados["clientes"] = [c for c in dados.get("clientes", []) if c.get("id") != cliente_id]
    salvar_dados(dados)

def _nome_display(c):
    if c["tipo"] == "PF":
        return c.get("nome", "") or "(sem nome)"
    return c.get("razao_social", "") or c.get("nome_fantasia", "") or "(sem razão social)"

def _endereco_completo(c):
    parts = [c.get("endereco",""), c.get("numero",""), c.get("complemento",""),
             c.get("bairro",""), c.get("cidade",""), c.get("estado",""), c.get("cep","")]
    return ", ".join(p for p in parts if p.strip())

