def tab_clientes_ui(dados, advogados_todos):
    st.markdown("## 👥 Clientes")

    # session state de navegação
    if "cli_view" not in st.session_state:
        st.session_state.cli_view = "lista"  # "lista" | "form" | "docs"
    if "cli_id"   not in st.session_state:
        st.session_state.cli_id = None
    if "cli_docs" not in st.session_state:
        st.session_state.cli_docs = {}

    # ─── LISTA ───────────────────────────────
    if st.session_state.cli_view == "lista":
        col_srch, col_btn = st.columns([4, 1])
        with col_srch:
            busca = st.text_input("🔍 Buscar cliente", placeholder="Nome, CPF, CNPJ ou telefone...", label_visibility="collapsed")
        with col_btn:
            if st.button("➕ Novo cliente", use_container_width=True):
                st.session_state.cli_id   = None
                st.session_state.cli_view = "form"
                st.rerun()

        clientes = dados.get("clientes", [])
        if busca.strip():
            termo = busca.strip().lower()
            clientes = [c for c in clientes if
                termo in _nome_display(c).lower() or
                termo in c.get("cpf","").lower() or
                termo in c.get("cnpj","").lower() or
                termo in c.get("razao_social","").lower() or
                termo in c.get("telefone","").lower()]

        if not clientes:
            st.info("Nenhum cliente cadastrado ainda. Clique em **➕ Novo cliente** para começar.")
            return

        for c in sorted(clientes, key=lambda x: _nome_display(x).lower()):
            icone = "👤" if c["tipo"] == "PF" else "🏢"
            nome_d = _nome_display(c)
            tel   = c.get("telefone","") or "—"
            with st.container(border=True):
                cc1, cc2, cc3, cc4 = st.columns([4,1,2,2])
                with cc1:
                    st.markdown(f"**{icone} {nome_d}**  \n📱 {tel}")
                with cc2:
                    st.markdown(f"`{c['tipo']}`")
                with cc3:
                    if st.button("✏️ Editar", key="edit_"+c["id"], use_container_width=True):
                        st.session_state.cli_id   = c["id"]
                        st.session_state.cli_view = "form"
                        st.rerun()
                with cc4:
                    if st.button("📄 Documentos", key="docs_"+c["id"], use_container_width=True):
                        st.session_state.cli_id   = c["id"]
                        st.session_state.cli_view = "docs"
                        st.rerun()

    # ─── FORM CADASTRO / EDIÇÃO ────────────────
    elif st.session_state.cli_view == "form":
        cid = st.session_state.cli_id
        clientes = dados.get("clientes", [])
        existente = next((c for c in clientes if c["id"] == cid), None) if cid else None
        is_novo = existente is None
        titulo = "➕ Novo Cliente" if is_novo else f"✏️ Editar: {_nome_display(existente)}"
        st.markdown(f"### {titulo}")

        tipo_default = existente["tipo"] if existente else "PF"
        tipo = st.radio("Tipo de cliente", ["PF", "PJ"],
                        index=0 if tipo_default=="PF" else 1, horizontal=True)

        c = existente.copy() if existente else _novo_cliente_vazio(tipo)

        st.markdown("#### Dados Pessoais / Empresariais")
        if tipo == "PF":
            col1, col2 = st.columns(2)
            with col1:
                c["nome"] = st.text_input("Nome completo *", value=c.get("nome",""))
                c["cpf"]  = st.text_input("CPF *", value=c.get("cpf",""), placeholder="000.000.000-00",
                                           key="fcpf", on_change=_fmt_cpf)
                c["rg"]   = st.text_input("RG", value=c.get("rg",""))
                c["orgao_rg"] = st.text_input("Órgão emissor RG", value=c.get("orgao_rg",""))
            with col2:
                c["estado_civil"]  = st.text_input("Estado civil", value=c.get("estado_civil",""),
                                                    placeholder="solteiro(a), casado(a)...")
                c["profissao"]     = st.text_input("Profissão", value=c.get("profissao",""))
                c["nacionalidade"] = st.text_input("Nacionalidade", value=c.get("nacionalidade","brasileiro(a)"))
                c["naturalidade"]  = st.text_input("Naturalidade", value=c.get("naturalidade",""),
                                                    placeholder="Cidade-UF")
        else:  # PJ
            col1, col2 = st.columns(2)
            with col1:
                c["razao_social"]  = st.text_input("Razão Social *", value=c.get("razao_social",""))
                c["cnpj"]          = st.text_input("CNPJ *", value=c.get("cnpj",""),
                                                    placeholder="00.000.000/0001-00",
                                                    key="fcnpj", on_change=_fmt_cnpj)
                c["nome_fantasia"] = st.text_input("Nome Fantasia", value=c.get("nome_fantasia",""))
            with col2:
                st.markdown("**Sócio / Responsável**")
                c["socio_nome"]  = st.text_input("Nome do sócio/responsável", value=c.get("socio_nome",""))
                c["socio_cpf"]   = st.text_input("CPF do sócio", value=c.get("socio_cpf",""))
                c["socio_rg"]    = st.text_input("RG do sócio", value=c.get("socio_rg",""))
                c["socio_cargo"] = st.text_input("Cargo/Função", value=c.get("socio_cargo",""),
                                                  placeholder="Sócio-administrador, Diretor...")

        st.markdown("#### Contato")
        col1, col2 = st.columns(2)
        with col1:
            c["telefone"] = st.text_input("Telefone / WhatsApp *", value=c.get("telefone",""),
                                           placeholder="(63) 99999-9999")
        with col2:
            c["email"] = st.text_input("E-mail", value=c.get("email",""))

        st.markdown("#### Endereço")
        col1, col2, col3 = st.columns([3,1,1])
        with col1:
            c["endereco"] = st.text_input("Rua / Avenida / Quadra *", value=c.get("endereco",""))
        with col2:
            c["numero"] = st.text_input("Número", value=c.get("numero",""))
        with col3:
            c["complemento"] = st.text_input("Complemento", value=c.get("complemento",""))
        col4, col5, col6, col7 = st.columns([2,2,1,1])
        with col4:
            c["bairro"] = st.text_input("Bairro", value=c.get("bairro",""))
        with col5:
            c["cidade"] = st.text_input("Cidade", value=c.get("cidade",""))
        with col6:
            c["estado"] = st.text_input("Estado", value=c.get("estado","TO"), max_chars=2)
        with col7:
            c["cep"] = st.text_input("CEP", value=c.get("cep",""), placeholder="00000-000")

        st.markdown("---")
        btn1, btn2, btn3 = st.columns([2,2,1])
        with btn1:
            if st.button("💾 Salvar cliente", type="primary", use_container_width=True):
                erros = []
                if tipo == "PF":
                    if not c["nome"].strip(): erros.append("Informe o nome completo.")
                    if not c["cpf"].strip():  erros.append("Informe o CPF.")
                else:
                    if not c["razao_social"].strip(): erros.append("Informe a razão social.")
                    if not c["cnpj"].strip():         erros.append("Informe o CNPJ.")
                if not c["telefone"].strip(): erros.append("Telefone/WhatsApp é obrigatório.")
                if not c["endereco"].strip(): erros.append("Informe o endereço.")
                if erros:
                    for e in erros: st.error(e)
                else:
                    c["tipo"] = tipo
                    if is_novo:
                        c["id"] = str(uuid.uuid4())[:8]
                    try:
                        salvar_cliente(dados, c)
                        st.success(f"✅ Cliente salvo com sucesso! (arquivo: {_DADOS_PATH})")
                        st.session_state.cli_view = "lista"
                        st.rerun()
                    except Exception as ex:
                        st.error(f"❌ Falha ao salvar: {ex}")
        with btn2:
            if not is_novo:
                if st.button("📄 Gerar Documentos", use_container_width=True):
                    salvar_cliente(dados, c)
                    st.session_state.cli_id   = c["id"]
                    st.session_state.cli_view = "docs"
                    st.rerun()
        with btn3:
            if st.button("← Voltar", use_container_width=True):
                st.session_state.cli_view = "lista"
                st.rerun()
        if not is_novo:
            st.markdown("---")
            with st.expander("⚠️ Zona de perigo"):
                if st.button("🗑️ Excluir este cliente", type="primary"):
                    excluir_cliente(dados, c["id"])
                    st.session_state.cli_view = "lista"
                    st.session_state.cli_id   = None
                    st.rerun()

    # ─── GERAÇÃO DE DOCUMENTOS ───────────────
    elif st.session_state.cli_view == "docs":
        cid = st.session_state.cli_id
        clientes = dados.get("clientes", [])
        c = next((x for x in clientes if x["id"] == cid), None)
        if not c:
            st.error("Cliente não encontrado.")
            st.session_state.cli_view = "lista"
            st.rerun()
            return

        nome_d = _nome_display(c)
        tipo_k = "pf" if c["tipo"] == "PF" else "pj"

        st.markdown(f"### 📄 Documentos — {nome_d}")
        if st.button("← Voltar para o cadastro"):
            st.session_state.cli_view = "form"
            st.rerun()

        # Resumo do cliente
        with st.expander("👤 Dados do cliente"):
            if c["tipo"] == "PF":
                st.write(f"**Nome:** {c.get('nome','')}  |  **CPF:** {c.get('cpf','')}  |  **RG:** {c.get('rg','')}")
                st.write(f"**Estado civil:** {c.get('estado_civil','')}  |  **Profissão:** {c.get('profissao','')}")
            else:
                st.write(f"**Razão Social:** {c.get('razao_social','')}  |  **CNPJ:** {c.get('cnpj','')}")
                st.write(f"**Sócio/Resp.:** {c.get('socio_nome','')} ({c.get('socio_cargo','')})")
            st.write(f"**Endereço:** {_endereco_completo(c)}")
            st.write(f"**Tel:** {c.get('telefone','')}  |  **E-mail:** {c.get('email','')}")

        st.divider()

        # Documentos a gerar
        col_a, col_b, col_c = st.columns(3)
        with col_a:
            gerar_proc = st.checkbox("📄 Procuração", value=True, key="dp_proc")
        with col_b:
            gerar_cont = st.checkbox("📑 Contrato de Honorários", key="dp_cont")
        with col_c:
            if tipo_k == "pf":
                gerar_decl = st.checkbox("📋 Declaração de Hiposuficiência", key="dp_decl")
            else:
                gerar_decl = False
                st.caption("Declaração: somente PF")

        # Advogados
        if (gerar_proc or gerar_cont) and advogados_todos:
            st.divider()
            st.subheader("Advogados Outorgados")
            opcoes = [f"{a['nome']} – {a['oab']}" for a in advogados_todos]
            sel = st.multiselect("Selecione o(s) advogado(s) *", options=opcoes,
                                  default=opcoes[:1] if opcoes else [], key="dp_adv")
            advogados_sel = [advogados_todos[opcoes.index(s)] for s in sel]
        elif gerar_proc or gerar_cont:
            advogados_sel = []
            st.warning("Nenhum advogado cadastrado. Acesse Administração.")
        else:
            advogados_sel = []

        # Objeto da ação
        if gerar_proc or gerar_cont:
            st.divider()
            st.subheader("Objeto da Ação")
            _obj_label = "Descreva a ação / serviço contratado *" if gerar_cont else "Descreva a ação / serviço contratado (opcional para procuração)"
            objeto_acao = st.text_area(_obj_label,
                                        placeholder="Ex: ação trabalhista em face de Empresa X Ltda.",
                                        help="Obrigatório para o Contrato. Na procuração, se deixado em branco, serão outorgados apenas poderes gerais (sem objeto específico).",
                                        key="dp_objeto")
        else:
            objeto_acao = ""

        # Honorários
        if gerar_cont:
            st.divider()
            st.subheader("Honorários")
            tipo_honorario = st.radio("Tipo", ["Percentual sobre o êxito", "Valor fixo"],
                                       horizontal=True, key="dp_thon")
            if tipo_honorario == "Percentual sobre o êxito":
                valor_honorario = st.text_input("Percentual (%)", placeholder="30", key="dp_vh")
                tipo_hon_key = "percentual"
                extenso_honorario = valor_honorario.strip() + " por cento" if valor_honorario.strip() else ""
            else:
                valor_honorario = st.text_input(
                    "Valor (R$)", placeholder="100.000,00", key="dp_vh",
                    on_change=_fmt_honorario_fixo, args=("dp_vh",))
                extenso_honorario = numero_por_extenso(valor_honorario) if valor_honorario.strip() else ""
                tipo_hon_key = "fixo"
        else:
            valor_honorario = ""; extenso_honorario = ""; tipo_hon_key = "percentual"

        st.divider()

        # Monta campos do cliente para os geradores
        if tipo_k == "pf":
            nome_doc   = c.get("nome","").strip()
            cpf_doc    = c.get("cpf","").strip()
            rg_doc     = c.get("rg","").strip() or None
            nac_doc    = c.get("nacionalidade","brasileiro(a)")
            nat_doc    = c.get("naturalidade","").strip()
            ecivil_doc = c.get("estado_civil","").strip()
            end_doc    = _endereco_completo(c)
        else:
            nome_doc   = c.get("razao_social","").strip()
            cpf_doc    = c.get("cnpj","").strip()
            rg_doc     = None; nac_doc = ""; nat_doc = ""; ecivil_doc = ""
            end_doc    = _endereco_completo(c)

        if st.button("📄 Gerar Documentos", type="primary"):
            erros = []
            if not (gerar_proc or gerar_cont or gerar_decl):
                erros.append("Selecione ao menos um documento.")
            if gerar_cont and not objeto_acao.strip():
                erros.append("Informe o objeto da ação (obrigatório para o Contrato de Honorários).")
            if (gerar_proc or gerar_cont) and not advogados_sel:
                erros.append("Selecione ao menos um advogado.")
            if gerar_cont:
                if not valor_honorario.strip(): erros.append("Informe o valor dos honorários.")
            if erros:
                for e in erros: st.error(e)
            else:
                with st.spinner("Gerando documento(s)..."):
                    nd = {"nome_limpo": nome_doc.replace(" ","_")[:40]}
                    if gerar_proc:
                        nd["proc"] = gerar_procuracao(
                            nome=nome_doc, cpf_cnpj=cpf_doc,
                            endereco=end_doc, tipo=tipo_k, rg=rg_doc,
                            nacionalidade=nac_doc, estado_civil=ecivil_doc,
                            objeto_acao=objeto_acao.strip(), advogados=advogados_sel)
                    if gerar_cont:
                        nd["cont"] = gerar_contrato(
                            nome=nome_doc, cpf_cnpj=cpf_doc,
                            endereco=end_doc, tipo=tipo_k, rg=rg_doc,
                            naturalidade=nat_doc, nacionalidade=nac_doc,
                            estado_civil=ecivil_doc, objeto_acao=objeto_acao.strip(),
                            tipo_honorario=tipo_hon_key,
                            valor_honorario=valor_honorario.strip(),
                            extenso_honorario=extenso_honorario.strip(),
                            advogados=advogados_sel)
                    if gerar_decl:
                        nd["decl"] = gerar_declaracao(
                            nome=nome_doc, nacionalidade=nac_doc,
                            estado_civil=ecivil_doc, cpf=cpf_doc,
                            rg=rg_doc, endereco=end_doc)
                    st.session_state.cli_docs = nd

        # Downloads
        docs = st.session_state.cli_docs
        if docs:
            nl = docs.get("nome_limpo","cliente")
            st.success("✅ Documentos prontos para download:")
            if "proc" in docs:
                st.download_button("⬇️ Baixar Procuração (.docx)", data=docs["proc"],
                                    file_name="Procuracao_"+nl+".docx",
                                    mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                                    key="dl_cli_proc")
            if "cont" in docs:
                st.download_button("⬇️ Baixar Contrato de Honorários (.docx)", data=docs["cont"],
                                    file_name="Contrato_"+nl+".docx",
                                    mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                                    key="dl_cli_cont")
            if "decl" in docs:
                st.download_button("⬇️ Baixar Declaração de Hiposuficiência (.docx)", data=docs["decl"],
                                    file_name="Declaracao_"+nl+".docx",
                                    mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                                    key="dl_cli_decl")

# ────────────────────────────────────────────
# APP PRINCIPAL
# ────────────────────────────────────────────
def app_principal():
    dados = carregar_dados()
    advogados_todos = dados.get("advogados", [])

    if "docs" not in st.session_state:
        st.session_state.docs = {}

    _css()
    # Header
    col_logo, col_info, col_sair = st.columns([1,4,1])
    with col_logo:
        st.image(_logo(), use_container_width=True)
    with col_info:
        st.markdown("""<div class="ptm-header">
            <div class="ptm-name">Poli, Tertuliano &amp; Mantovani – Advogados Associados</div>
            <div class="ptm-sub">Sistema de Geração de Documentos</div>
        </div>""", unsafe_allow_html=True)
    with col_sair:
        st.write("")
        if st.button("Sair", key="logout"):
            for k in ["autenticado","usuario","nome_usuario","is_admin"]:
                st.session_state.pop(k, None)
            st.rerun()
        st.caption(st.session_state.nome_usuario)
    st.divider()

    # Tabs: admin vê "Clientes" + "Admin" + "Minha Conta", usuário vê "Clientes" + "Minha Conta"
    if st.session_state.get("is_admin"):
        tab_cli, tab_adm, tab_conta = st.tabs(["👥 Clientes", "⚙️ Administração", "👤 Minha Conta"])
    else:
        tab_cli, tab_conta = st.tabs(["👥 Clientes", "👤 Minha Conta"])
        tab_adm = None

    with tab_cli:
        tab_clientes_ui(dados, advogados_todos)

    # ─── TAB LEGADO (não mais usada diretamente, mantida via tab_clientes_ui) ───
    if False:
        # ── Tipo PJ/PF ──
        tipo = st.radio("Tipo do cliente", ["Pessoa Física", "Pessoa Jurídica"], horizontal=True)
        tipo_key = "pf" if tipo == "Pessoa Física" else "pj"

        # ── Dados básicos ──
        st.subheader("Dados do Cliente")
        col1, col2 = st.columns(2)
        with col1:
            nome = st.text_input("Nome / Razão Social *")
        with col2:
            if tipo_key == "pj":
                cpf_cnpj = st.text_input("CNPJ *", placeholder="00.000.000/0001-00",
                                          key="cnpj_input", on_change=_fmt_cnpj)
                rg = None; naturalidade = ""; nacionalidade = "brasileiro(a)"; estado_civil = ""
            else:
                cpf_cnpj = st.text_input("CPF *", placeholder="000.000.000-00",
                                          key="cpf_input", on_change=_fmt_cpf)

        if tipo_key == "pf":
            col3, col4 = st.columns(2)
            with col3:
                rg_input = st.text_input("RG", placeholder="Deixe em branco se não houver")
                rg = rg_input.strip() if rg_input.strip() else None
            with col4:
                naturalidade = st.text_input("Naturalidade", placeholder="Cidade-UF de nascimento")
            col5, col6 = st.columns(2)
            with col5:
                nacionalidade = st.text_input("Nacionalidade", value="brasileiro(a)")
            with col6:
                estado_civil = st.text_input("Estado civil", placeholder="solteiro(a), casado(a)...")

        endereco_label = "Endereço / Sede *" if tipo_key == "pj" else "Endereço completo *"
        endereco = st.text_input(endereco_label, placeholder="Rua, número, bairro, cidade – UF, CEP")

        # ── Documentos a gerar ──
        st.divider()
        st.subheader("Documentos a Gerar")
        col_a, col_b, col_c = st.columns(3)
        with col_a:
            gerar_proc = st.checkbox("📄 Procuração", value=True)
        with col_b:
            gerar_cont = st.checkbox("📑 Contrato de Honorários")
        with col_c:
            if tipo_key == "pf":
                gerar_decl = st.checkbox("📋 Declaração de Hiposuficiência")
            else:
                gerar_decl = False
                st.caption("Declaração: somente Pessoa Física")

        # ── Seleção de advogados outorgados ──
        if (gerar_proc or gerar_cont) and advogados_todos:
            st.divider()
            st.subheader("Advogados Outorgados")
            opcoes = [f"{a['nome']} – {a['oab']}" for a in advogados_todos]
            sel = st.multiselect(
                "Selecione o(s) advogado(s) outorgado(s) *",
                options=opcoes,
                default=opcoes[:1] if opcoes else [],
                help="Marque os advogados que constarão na Procuração e no Contrato."
            )
            advogados_sel = [advogados_todos[opcoes.index(s)] for s in sel]
        elif gerar_proc or gerar_cont:
            advogados_sel = []
            st.warning("Nenhum advogado cadastrado. Acesse o Painel Admin para adicionar.")
        else:
            advogados_sel = []

        # ── Objeto da ação ──
        if gerar_proc or gerar_cont:
            st.divider()
            st.subheader("Objeto da Ação")
            _obj_label2 = "Descreva a ação / serviço contratado *" if gerar_cont else "Descreva a ação / serviço contratado (opcional para procuração)"
            objeto_acao = st.text_area(
                _obj_label2,
                placeholder="Ex: ação trabalhista em face de Empresa X Ltda.",
                help="Obrigatório para o Contrato. Na procuração, se deixado em branco, serão outorgados apenas poderes gerais (sem objeto específico)."
            )
        else:
            objeto_acao = ""

        # ── Honorários ──
        if gerar_cont:
            st.divider()
            st.subheader("Honorários")
            tipo_honorario = st.radio(
                "Tipo de honorários",
                ["Percentual sobre o êxito", "Valor fixo"],
                horizontal=True,
                key="tipo_hon"
            )
            if tipo_honorario == "Percentual sobre o êxito":
                valor_honorario = st.text_input("Percentual (%)", placeholder="30", key="av_vh")
                tipo_hon_key = "percentual"
                extenso_honorario = valor_honorario.strip() + " por cento" if valor_honorario.strip() else ""
            else:
                valor_honorario = st.text_input(
                    "Valor (R$)", placeholder="100.000,00", key="av_vh",
                    on_change=_fmt_honorario_fixo, args=("av_vh",))
                extenso_honorario = numero_por_extenso(valor_honorario) if valor_honorario.strip() else ""
                tipo_hon_key = "fixo"
        else:
            valor_honorario = ""; extenso_honorario = ""; tipo_hon_key = "percentual"

        st.divider()

        # ── Botão gerar ──
        if st.button("📄 Gerar Documentos"):
            erros = []
            if not nome.strip(): erros.append("Informe o nome / razão social.")
            if not cpf_cnpj.strip(): erros.append("Informe o CPF/CNPJ.")
            if not endereco.strip(): erros.append("Informe o endereço.")
            if not (gerar_proc or gerar_cont or gerar_decl):
                erros.append("Selecione ao menos um documento para gerar.")
            if gerar_cont and not objeto_acao.strip():
                erros.append("Informe o objeto da ação (obrigatório para o Contrato de Honorários).")
            if (gerar_proc or gerar_cont) and not advogados_sel:
                erros.append("Selecione ao menos um advogado outorgado.")
            if gerar_cont:
                if not valor_honorario.strip(): erros.append("Informe o valor dos honorários.")

            if erros:
                for e in erros:
                    st.error(e)
            else:
                with st.spinner("Gerando documento(s)..."):
                    nome_limpo = nome.strip().replace(" ","_")[:40]
                    novos_docs = {"nome_limpo": nome_limpo}
                    if gerar_proc:
                        novos_docs["proc"] = gerar_procuracao(
                            nome=nome.strip(), cpf_cnpj=cpf_cnpj.strip(),
                            endereco=endereco.strip(), tipo=tipo_key, rg=rg,
                            nacionalidade=nacionalidade if tipo_key=="pf" else "",
                            estado_civil=estado_civil.strip() if tipo_key=="pf" else "",
                            objeto_acao=objeto_acao.strip(),
                            advogados=advogados_sel,
                        )
                    if gerar_cont:
                        novos_docs["cont"] = gerar_contrato(
                            nome=nome.strip(), cpf_cnpj=cpf_cnpj.strip(),
                            endereco=endereco.strip(), tipo=tipo_key, rg=rg,
                            naturalidade=naturalidade.strip() if tipo_key=="pf" else "",
                            nacionalidade=nacionalidade if tipo_key=="pf" else "",
                            estado_civil=estado_civil.strip() if tipo_key=="pf" else "",
                            objeto_acao=objeto_acao.strip(),
                            tipo_honorario=tipo_hon_key,
                            valor_honorario=valor_honorario.strip(),
                            extenso_honorario=extenso_honorario.strip(),
                            advogados=advogados_sel,
                        )
                    if gerar_decl:
                        novos_docs["decl"] = gerar_declaracao(
                            nome=nome.strip(), nacionalidade=nacionalidade,
                            estado_civil=estado_civil.strip(), cpf=cpf_cnpj.strip(),
                            rg=rg, endereco=endereco.strip(),
                        )
                    st.session_state.docs = novos_docs

        # ── Downloads persistentes ──
        docs = st.session_state.docs
        if docs:
            st.success("✅ Documentos prontos para download:")
            nome_limpo = docs.get("nome_limpo","cliente")
            if "proc" in docs:
                st.download_button(
                    label="⬇️ Baixar Procuração (.docx)",
                    data=docs["proc"],
                    file_name="Procuracao_"+nome_limpo+".docx",
                    mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                    key="dl_proc"
                )
            if "cont" in docs:
                st.download_button(
                    label="⬇️ Baixar Contrato de Honorários (.docx)",
                    data=docs["cont"],
                    file_name="Contrato_"+nome_limpo+".docx",
                    mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                    key="dl_cont"
                )
            if "decl" in docs:
                st.download_button(
                    label="⬇️ Baixar Declaração de Hiposuficiência (.docx)",
                    data=docs["decl"],
                    file_name="Declaracao_Hiposuficiencia_"+nome_limpo+".docx",
                    mime="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                    key="dl_decl"
                )

    if tab_adm is not None:
        with tab_adm:
            painel_admin(dados)

    with tab_conta:
        st.subheader("👤 Minha Conta")
        usuario_atual = st.session_state.get("usuario", "")
        nome_atual    = st.session_state.get("nome_usuario", "")
        st.write(f"**Usuário:** `{usuario_atual}`")
        st.write(f"**Nome:** {nome_atual}")
        st.divider()
        st.markdown("#### Trocar Senha")
        senha_atual  = st.text_input("Senha atual", type="password", key="cc_atual")
        senha_nova   = st.text_input("Nova senha", type="password", key="cc_nova")
        senha_conf   = st.text_input("Confirmar nova senha", type="password", key="cc_conf")
        if st.button("Salvar nova senha", key="cc_salvar"):
            if not senha_atual or not senha_nova or not senha_conf:
                st.error("Preencha todos os campos.")
            elif senha_nova != senha_conf:
                st.error("Nova senha e confirmação não coincidem.")
            elif len(senha_nova) < 4:
                st.error("A nova senha deve ter pelo menos 4 caracteres.")
            else:
                d = carregar_dados()
                u = d.get("usuarios", {}).get(usuario_atual)
                if u and _ok(senha_atual, u["hash"]):
                    d["usuarios"][usuario_atual]["hash"] = _hash(senha_nova)
                    salvar_dados(d)
                    st.success("Senha alterada com sucesso!")
                else:
                    st.error("Senha atual incorreta.")

